{args_doc, state} =
  Enum.reduce(args, {[], state}, fn quoted, {acc, state} ->
    {doc, state} = quoted_to_algebra(quoted, :block, state)
    doc = doc |> concat(nest(break(""), :reset)) |> group()
    {[doc | acc], state}
  end)
